ee:message.ee:set-payload:
%dw 2.0
output application/json
var sapiErr = if (vars.sapiErrorPayload is Object) vars.sapiErrorPayload else {}
---
{
	correlationId: vars.correlationId default correlationId,
	operation: vars.operation default "UNKNOWN",
	orderId: if (!isEmpty(vars.orderId default "")) 
            vars.orderId 
          else 
            (vars.sapiErrorPayload.orderId default null),
	originalPayload: vars.rawMessage default payload,
	errorDetails: {
		errorCode: sapiErr.errorCode default error.errorType.identifier default "BUSINESS_ERROR",
		errorNamespace: sapiErr.errorNamespace default "APP",
		description: sapiErr.errorMessage default sapiErr.description default (vars.sapiErrorPayload as String default error.description default "Processing failed"),
		apiResponseBody: vars.sapiErrorPayload default null,
		timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"}
	}
}
